/* ---------- سكن البطاقة: للماسية وفوق يختار شكل بطاقته (ومستواه الحقيقي يبقى مكتوب) ---------- */
const SKIN_BASE = ['classic', 'bronze', 'silver', 'emerald', 'gold', 'ruby', 'diamond', 'legend'];
const SKIN_MIN = { classic: 0, bronze: 50, silver: 100, emerald: 300, gold: 500, ruby: 750, diamond: 1000, legend: 2000, night: 1000, marble: 2000, desert: 2000 };
function setSkin(token, skin) {
  const t = memberByToken_(token);
  if (!t) throw new Error('سجّل دخولك من جديد');
  const m = findRow_(t.phone);
  skin = String(skin || '');
  const lvl = m.legend ? 2000 : m.vip ? Math.max(1000, m.peak, m.points) : Math.max(m.peak, m.points);
  if (lvl < 1000) throw new Error('تغيير شكل البطاقة متاح من البطاقة الماسية وفوق 💎');
  if (skin && !(skin in SKIN_MIN)) throw new Error('شكل غير معروف');
  if (skin && SKIN_MIN[skin] > lvl) throw new Error('هذا الشكل يحتاج مستوى أعلى');
  const sh = members_();
  if (!sh.getRange(1, 14).getValue()) sh.getRange(1, 14).setValue('شكل البطاقة').setFontWeight('bold');
  sh.getRange(m.row, 14).setValue(skin);
  return { skin: skin };
}

