// صور الموهيتو: تربط كل موهيتو في ورقة المنيو بصورته
function setMojitoImages() {
  const B = 'https://faresgaemr.github.io/RYA-COFFEE/menu/';
  const map = [[/ازرق|أزرق|بلو/, 'i8'], [/عنب/, 'i9'], [/فراول/, 'i10'], [/خوخ/, 'i11'], [/مشكل|ميكس/, 'i12'], [/rya|ريا/i, 'i13']];
  const sh = menu_(), data = sh.getDataRange().getValues(); let n = 0;
  for (let i = 1; i < data.length; i++) {
    const name = String(data[i][1]);
    if (name.indexOf('موهيتو') < 0) continue;
    const hit = map.find(x => x[0].test(name));
    if (hit) { sh.getRange(i + 1, 7).setValue(B + hit[1] + '.jpg'); n++; Logger.log(name + ' ← ' + hit[1]); }
    else Logger.log('ما لقيت صورة لـ: ' + name);
  }
  Logger.log('انربطت ' + n + ' صورة موهيتو ✅');
}
